const fs = require('node:fs')
const path = require('node:path')
const constants = require('../constants.js')

const target = path.join(__dirname, '..', 'constants.d.ts')
const declarations = Object.entries(constants).map(([name, value]) =>
  `export declare const ${name}: 0x${value.toString(16)}`
)
const contents = [
  '// SPDX-License-Identifier: AGPL-3.0-only',
  '// Generated by node scripts/generate-constant-types.cjs.',
  ...declarations,
  '',
  "declare const CK: Readonly<Omit<typeof import('./constants.js'), 'default'> & Record<string, number>>",
  'export default CK',
  '',
].join('\n')

if (process.argv.includes('--check')) {
  if (fs.readFileSync(target, 'utf8') !== contents) {
    console.error('Regenerate constants.d.ts with node scripts/generate-constant-types.cjs')
    process.exitCode = 1
  }
} else {
  fs.writeFileSync(target, contents)
}
